SELECT tb_date_list.datew, tb_date_list.snif, tb_date_list.qhour, tb_date_list.qhoure, Trim$(nz([fname]))+" "+Trim$(nz([pname])) & " טל: " & IIf(nz([sel])<>"",nz([sel]),nz([tel])) AS name, tb_date_list.mem
FROM ((tb_date_list LEFT JOIN cust_list ON tb_date_list.codel=cust_list.numw) INNER JOIN tmp_parameters ON tb_date_list.datew=tmp_parameters.wdate) INNER JOIN qsnif ON tb_date_list.snif=qsnif.qsnif
ORDER BY tb_date_list.snif, tb_date_list.qhour;

SELECT tb_yoman.*, tb_yoman.p AS q
FROM tb_yoman
WHERE (((tb_yoman.p)=True));
